import { readFileSync } from 'node:fs';
import { installSource } from './source-loader.ts';
import type { ISourcePlan } from './source-plan.ts';

// Generated by the canonical common-policy resolver, never developer bootstrap.
const filename = process.env.OTELC_NODE_PLAN;
if (!filename) throw new Error('otelc source bootstrap requires a generated plan');
const plan = JSON.parse(readFileSync(filename, 'utf8')) as ISourcePlan;
delete process.env.OTELC_NODE_PLAN;
const application = await installSource(plan);

// Observe after application exit listeners without adding asynchronous work to
// beforeExit. Synthetic exit events only checkpoint: actual FIFO EOF owns drain.
const emit = process.emit;
process.emit = function emitWithCheckpoint(this: NodeJS.Process, event: string | symbol, ...args: unknown[]): boolean {
  try { return Reflect.apply(emit, this, [event, ...args]); }
  finally {
    if (this === process && event === 'exit') {
      try { application.runtime.checkpoint(); }
      catch { /* Missing producer evidence invalidates qualification, never the application's exit code. */ }
    }
  }
} as typeof process.emit;
Object.defineProperty(process.emit, 'name', { value: emit.name, configurable: true });
Object.defineProperty(process.emit, 'length', { value: emit.length, configurable: true });
